#!/usr/bin/env python3
from pwn import *

def main():
    conn = remote('forensics.chal.csaw.io', 5000)

    while True:
        data = conn.recvuntil(b'> ', drop=True).decode('utf-8')
        print(data)

        # Check if we received the flag
        if 'flag{' in data:
            print("Found the flag!")
            break

        # Parse the question and provide answer
        if "Company Name" in data:
            conn.sendline(b"MI6")
        elif "Username" in data:
            conn.sendline(b"YourAnswer")
        # Add more conditions for other questions
        else:
            answer = input("Enter answer: ")
            conn.sendline(answer.encode())

if __name__ == "__main__":
    main()
